import { hmacSigner } from "../src/sign.ts";

// Test vectors for the request signer.
export const vectors = [
  { method: "GET", path: "/v1/items", body: "" },
  { method: "POST", path: "/v1/items", body: "{\"a\":1}" },
];

export async function run(secret: string) {
  const s = hmacSigner(secret, "test-key");
  return Promise.all(vectors.map(v => s.sign(v.method, v.path, v.body)));
}
